public class PMTask1 {
    private static String stripComment(String s) {
        StringBuilder out = new StringBuilder();
        boolean q = false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\"') q = !q;
            if (!q && (c == '#' || c == ';')) break;
            out.append(c);
        }
        return out.toString();
    }

    private static String unquote(String s) {
        return s.length() >= 2 && s.startsWith("\"") && s.endsWith("\"") ? s.substring(1, s.length() - 1) : s;
    }

    // Parse properties: first '=' or ':' outside quotes separates key/value.
    // Lines ending in backslash continue onto the next line with leading spaces trimmed.
    // # and ; are comments only outside double quotes.
    public static Map<String, String> parseProperties(String text) {
