import java.util.LinkedHashMap;
import java.util.Map;

public class PMTask3 {
    // Manifest parser:
    // - [section] prefixes following keys as section.key
    // - lines ending in backslash continue with the next physical line
    // - blank lines and # comments are ignored
    public static Map<String, String> parseManifest(String text) {

golden_completion:
Map<String, String> result = new LinkedHashMap<>();
String section = "";
StringBuilder joined = new StringBuilder();
for (String raw : text.split("\n", -1)) {
    if (raw.endsWith("\\")) { joined.append(raw, 0, raw.length() - 1); continue; }
    joined.append(raw);
    String line = joined.toString().trim(); joined.setLength(0);
    if (line.isEmpty() || line.startsWith("#")) continue;
    if (line.startsWith("[") && line.endsWith("]")) section = line.substring(1, line.length() - 1).trim();
    else { int eq = line.indexOf('='); if (eq >= 0) result.put((section.isEmpty() ? "" : section + ".") + line.substring(0, eq).trim(), line.substring(eq + 1).trim()); }
}
return result;

suffix:
    }

    public static void main(String[] args) {
        String cfg = "[core]\n" +
                     "name=dev\\\n" +
                     "bench\n" +
                     "# ignored\n" +
                     "[limits]\n" +
                     "score = 54";
        Map<String, String> m = parseManifest(cfg);
        assert m.get("core.name").equals("devbench") : m;
        assert m.get("limits.score").equals("54") : m;
        assert !m.containsKey("# ignored") : "comments skipped";
        assert m.size() == 2 : "size: " + m;
        System.out.println("OK");
    }
}

