    String[] lines = text.split("\n");

    for (String line : lines) {
        line = line.trim();
        if (line.isEmpty() || line.startsWith("#")) {
            continue;
        }

        if (line.endsWith("\\")) {
            currentLine.append(line.substring(0, line.length() - 1));
            continue;
        } else {
            currentLine.append(line);
        }

