            StringBuilder rev = new StringBuilder();
            for (char c : standard[i].toCharArray()) {
                rev.append(c == '.' ? '-' : '.');
            }
            MORSE.put((char)('A' + i), rev.toString());
        }
        String[] digits = {"-----",".----","..---","...--","....-",
            ".....","-....","--...","---..","----."};
        for (int i = 0; i < 10; i++) {
            StringBuilder rev = new StringBuilder();
            for (char c : digits[i].toCharArray()) {
                rev.append(c == '.' ? '-' : '.');
