import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;

public class PMTask17 {
    private static final Map<Character, Character> PAIRS = Map.of(
        '(', ')', '[', ']', '{', '}'
    );

    public static boolean isBalancedCode(String text) {

golden_completion:
Deque<Character> stack = new ArrayDeque<>();
boolean inStr = false;
for (int i = 0; i < text.length(); i++) {
    char ch = text.charAt(i);
    if (inStr) { if (ch == '\\' && i+1 < text.length()) { i++; } else if (ch == '"') inStr = false; }
    else if (ch == '"') inStr = true;
    else if (PAIRS.containsKey(ch)) stack.push(PAIRS.get(ch));
    else if (PAIRS.containsValue(ch) && (stack.isEmpty() || stack.peek() != ch)) return false;
    else if (PAIRS.containsValue(ch)) stack.pop();
}
return stack.isEmpty() && !inStr;

suffix:
    }

    public static void main(String[] args) {
        // isBalancedCode: bracket matching that ignores brackets inside "strings"
        // Handles \" escape sequences inside strings
        assert isBalancedCode("f(x)") == true;
        assert isBalancedCode("f(\"(\")") == true : "bracket inside string ignored";
        assert isBalancedCode("x = \"(\"") == true : "unmatched bracket in string is OK";
        assert isBalancedCode("{[()]}") == true;
        assert isBalancedCode("{[(])}") == false : "mismatched brackets";
        assert isBalancedCode("f(\") + g(") == false : "unmatched paren outside string";
        System.out.println("OK");
    }
}

