public class PMTask34 {
    // Bracket-aware CSV field splitter: splits on commas, but commas inside
    // matched brackets (parentheses, square, curly) are NOT delimiters.
    // Brackets can nest. Unmatched brackets are treated as regular characters.
    // Fields are trimmed of leading/trailing whitespace.

    public static List<String> splitFields(String line) {

golden_completion:
