StringBuilder cur = new StringBuilder();
int depth = 0;
for (int i = 0; i < line.length(); i++) {
    char c = line.charAt(i);
    if ("([{".indexOf(c) >= 0) { depth++; cur.append(c); }
    else if (")]}".indexOf(c) >= 0 && depth > 0) { depth--; cur.append(c); }
    else if (c == ',' && depth == 0) { fields.add(cur.toString().trim()); cur.setLength(0); }
    else cur.append(c);
}
fields.add(cur.toString().trim());
return fields;

