    }

    public static void main(String[] args) {
        List<String> r1 = splitFields("a, b, c");
        assert r1.size() == 3 : "size: " + r1.size();
        assert r1.get(0).equals("a") : r1.get(0);
        assert r1.get(1).equals("b") : r1.get(1);
        // Commas inside brackets are preserved
        List<String> r2 = splitFields("f(a,b), g(c,d)");
        assert r2.size() == 2 : "r2 size: " + r2.size();
        assert r2.get(0).equals("f(a,b)") : r2.get(0);
        assert r2.get(1).equals("g(c,d)") : r2.get(1);
        // Nested brackets
