public class PMTask35 {
    // INI-style config parser with line continuation (trailing backslash)
    // Lines ending with \ are joined with the next line (backslash removed).
    // Lines starting with # or ; are comments. Empty lines are skipped.
    // Format: key = value (spaces around = are trimmed)
    // No section headers — flat key-value.

    public static Map<String, String> parseConfig(String text) {

golden_completion:
Map<String, String> result = new LinkedHashMap<>();
StringBuilder pending = new StringBuilder();
for (String raw : text.split("\n", -1)) {
    if (raw.endsWith("\\")) { pending.append(raw, 0, raw.length() - 1); continue; }
    pending.append(raw);
    String line = pending.toString().trim();
    pending.setLength(0);
    if (line.isEmpty() || line.startsWith("#") || line.startsWith(";")) continue;
    int eq = line.indexOf('=');
    if (eq >= 0) result.put(line.substring(0, eq).trim(), line.substring(eq + 1).trim());
}
return result;

suffix:
    }

    public static void main(String[] args) {
        String cfg = "name = Alice\n" +
                     "# comment\n" +
                     "path = /home/\\\n" +
                     "alice/docs\n" +
                     "; another comment\n" +
                     "count = 42";
        Map<String, String> m = parseConfig(cfg);
        assert m.size() == 3 : "size: " + m.size();
        assert m.get("name").equals("Alice") : "name: " + m.get("name");
        assert m.get("path").equals("/home/alice/docs") : "path: " + m.get("path");
        assert m.get("count").equals("42") : "count";
        System.out.println("OK");
    }
}

