    // Edit distance: sub cost = 1 if same class, 3 if cross-class.
    // Insert/delete always cost 1.
    public static int editDistance(String s, String t) {
        int m = s.length(), n = t.length();
        int[][] dp = new int[m + 1][n + 1];
